	wQuota := params.BeaconConfig().MaxRequestBlobSidecars
	if slots.ToEpoch(s.cfg.clock.CurrentSlot()) >= params.BeaconConfig().ElectraForkEpoch {
		wQuota = params.BeaconConfig().MaxRequestBlobSidecarsElectra
	}
